## Component: `src/applicationData.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ApplicationDataArgs {
    environment: pulumi.Input<"dev" | "prod">;

    vpcId: pulumi.Input<string>;
    privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * Security groups whose members may connect to PostgreSQL.
     * Typically this is the EKS worker-node or pod security group.
     */
    databaseClientSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * IRSA/OIDC provider created for the EKS cluster.
     */
    oidcProviderArn: pulumi.Input<string>;
    oidcProviderUrl: pulumi.Input<string>;

    kubernetesNamespace?: pulumi.Input<string>;
    kubernetesServiceAccount?: pulumi.Input<string>;

    databaseName?: pulumi.Input<string>;
    databaseUsername?: pulumi.Input<string>;
    databasePassword: pulumi.Input<string>;

    databaseInstanceClass: pulumi.Input<string>;
    databaseMultiAz: pulumi.Input<boolean>;

    /**
     * AWS provider for us-west-2. Required when replication is enabled.
     */
    replicationProvider?: aws.Provider;

    enableReplication?: boolean;
    createDevIamUser?: boolean;

    tags?: pulumi.Input<Record<string, pulumi.Input<string>>>;
}

export class ApplicationData extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly bucketArn: pulumi.Output<string>;

    public readonly replicaBucket?: aws.s3.BucketV2;

    public readonly database: aws.rds.Instance;
    public readonly databaseSecurityGroup: aws.ec2.SecurityGroup;

    public readonly serviceAccountRole: aws.iam.Role;
    public readonly serviceAccountRoleArn: pulumi.Output<string>;

    public readonly devIamUser?: aws.iam.User;
    public readonly devAccessKey?: aws.iam.AccessKey;

    /**
     * Pulumi secret output. It is encrypted in Pulumi state.
     */
    public readonly databaseConnectionString: pulumi.Output<string>;

    constructor(
        name: string,
        args: ApplicationDataArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("example:application:ApplicationData", name, {}, opts);

        const childOpts: pulumi.ResourceOptions = { parent: this };

        const namespace = args.kubernetesNamespace ?? "default";
        const serviceAccount = args.kubernetesServiceAccount ?? "web-service";
        const databaseName = args.databaseName ?? "app";
        const databaseUsername = args.databaseUsername ?? "app_admin";

        const tags = pulumi
            .all([args.environment, args.tags ?? {}])
            .apply(([environment, additionalTags]) => ({
                Environment: environment,
                ManagedBy: "Pulumi",
                Component: name,
                ...additionalTags,
            }));

        // ---------------------------------------------------------------------
        // Primary S3 bucket
        // ---------------------------------------------------------------------

        this.bucket = new aws.s3.BucketV2(
            `${name}-assets`,
            {
                forceDestroy: false,
                tags,
            },
            childOpts,
        );

        this.bucketArn = this.bucket.arn;

        const primaryVersioning = new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: this.bucket.id,
                versioningConfiguration: {
                    status: "Enabled",
                },
            },
            childOpts,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: this.bucket.id,
                rules: [
                    {
                        applyServerSideEncryptionByDefault: {
                            sseAlgorithm: "AES256",
                        },
                        bucketKeyEnabled: false,
                    },
                ],
            },
            childOpts,
        );

        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-public-access`,
            {
                bucket: this.bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOpts,
        );

        // ---------------------------------------------------------------------
        // Production cross-region replication
        // ---------------------------------------------------------------------

        if (args.enableReplication) {
            if (!args.replicationProvider) {
                throw new Error(
                    "replicationProvider is required when enableReplication is true",
                );
            }

            const replicaOpts: pulumi.ResourceOptions = {
                parent: this,
                provider: args.replicationProvider,
            };

            this.replicaBucket = new aws.s3.BucketV2(
                `${name}-assets-replica`,
                {
                    forceDestroy: false,
                    tags,
                },
                replicaOpts,
            );

            const replicaVersioning = new aws.s3.BucketVersioningV2(
                `${name}-assets-replica-versioning`,
                {
                    bucket: this.replicaBucket.id,
                    versioningConfiguration: {
                        status: "Enabled",
                    },
                },
                replicaOpts,
            );

            new aws.s3.BucketServerSideEncryptionConfigurationV2(
                `${name}-assets-replica-encryption`,
                {
                    bucket: this.replicaBucket.id,
                    rules: [
                        {
                            applyServerSideEncryptionByDefault: {
                                sseAlgorithm: "AES256",
                            },
                        },
                    ],
                },
                replicaOpts,
            );

            new aws.s3.BucketPublicAccessBlock(
                `${name}-assets-replica-public-access`,
                {
                    bucket: this.replicaBucket.id,
                    blockPublicAcls: true,
                    blockPublicPolicy: true,
                    ignorePublicAcls: true,
                    restrictPublicBuckets: true,
                },
                replicaOpts,
            );

            const replicationRole = new aws.iam.Role(
                `${name}-replication`,
                {
                    assumeRolePolicy: aws.iam.getPolicyDocumentOutput({
                        statements: [
                            {
                                effect: "Allow",
                                principals: [
                                    {
                                        type: "Service",
                                        identifiers: ["s3.amazonaws.com"],
                                    },
                                ],
                                actions: ["sts:AssumeRole"],
                            },
                        ],
                    }).json,
                    tags,
                },
                childOpts,
            );

            const replicationPolicy = new aws.iam.Policy(
                `${name}-replication`,
                {
                    description: "Allows replication of application asset objects",
                    policy: pulumi
                        .all([this.bucket.arn, this.replicaBucket.arn])
                        .apply(([sourceArn, destinationArn]) =>
                            JSON.stringify({
                                Version: "2012-10-17",
                                Statement: [
                                    {
                                        Sid: "ReadSourceBucketConfiguration",
                                        Effect: "Allow",
                                        Action: [
                                            "s3:GetReplicationConfiguration",
                                            "s3:ListBucket",
                                        ],
                                        Resource: sourceArn,
                                    },
                                    {
                                        Sid: "ReadSourceObjectVersions",
                                        Effect: "Allow",
                                        Action: [
                                            "s3:GetObjectVersion",
                                            "s3:GetObjectVersionAcl",
                                            "s3:GetObjectVersionTagging",
                                        ],
                                        Resource: `${sourceArn}/*`,
                                    },
                                    {
                                        Sid: "ReplicateToDestination",
                                        Effect: "Allow",
                                        Action: [
                                            "s3:ReplicateObject",
                                            "s3:ReplicateDelete",
                                            "s3:ReplicateTags",
                                        ],
                                        Resource: `${destinationArn}/*`,
                                    },
                                ],
                            }),
                        ),
                    tags,
                },
                childOpts,
            );

            new aws.iam.RolePolicyAttachment(
                `${name}-replication`,
                {
                    role: replicationRole.name,
                    policyArn: replicationPolicy.arn,
                },
                childOpts,
            );

            new aws.s3.BucketReplicationConfig(
                `${name}-assets-replication`,
                {
                    bucket: this.bucket.id,
                    role: replicationRole.arn,
                    rules: [
                        {
                            id: "replicate-all-assets",
                            status: "Enabled",
                            destination: {
                                bucket: this.replicaBucket.arn,
                                storageClass: "STANDARD",
                            },
                            deleteMarkerReplication: {
                                status: "Enabled",
                            },
                            filter: {},
                        },
                    ],
                },
                {
                    parent: this,
                    dependsOn: [primaryVersioning, replicaVersioning],
                },
            );
        }

        // ---------------------------------------------------------------------
        // IAM role for the Kubernetes service account
        // ---------------------------------------------------------------------

        const issuerHostPath = pulumi.output(args.oidcProviderUrl).apply(
            url => url.replace(/^https:\/\//, "").replace(/\/$/, ""),
        );

        const assumeRolePolicy = pulumi
            .all([
                args.oidcProviderArn,
                issuerHostPath,
                namespace,
                serviceAccount,
            ])
            .apply(([providerArn, issuer, ns, sa]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Principal: {
                                Federated: providerArn,
                            },
                            Action: "sts:AssumeRoleWithWebIdentity",
                            Condition: {
                                StringEquals: {
                                    [`${issuer}:aud`]: "sts.amazonaws.com",
                                    [`${issuer}:sub`]:
                                        `system:serviceaccount:${ns}:${sa}`,
                                },
                            },
                        },
                    ],
                }),
            );

        this.serviceAccountRole = new aws.iam.Role(
            `${name}-service-account`,
            {
                assumeRolePolicy,
                description: "IRSA role for the application service account",
                tags,
            },
            childOpts,
        );

        this.serviceAccountRoleArn = this.serviceAccountRole.arn;

        const servicePolicy = new aws.iam.Policy(
            `${name}-service`,
            {
                description: "Least-privilege access to application assets",
                policy: this.bucket.arn.apply(bucketArn =>
                    JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [
                            {
                                Sid: "ListAssetBucket",
                                Effect: "Allow",
                                Action: ["s3:ListBucket"],
                                Resource: bucketArn,
                            },
                            {
                                Sid: "ReadWriteAssetObjects",
                                Effect: "Allow",
                                Action: [
                                    "s3:GetObject",
                                    "s3:PutObject",
                                    "s3:DeleteObject",
                                ],
                                Resource: `${bucketArn}/*`,
                            },
                        ],
                    }),
                ),
                tags,
            },
            childOpts,
        );

        new aws.iam.RolePolicyAttachment(
            `${name}-service`,
            {
                role: this.serviceAccountRole.name,
                policyArn: servicePolicy.arn,
            },
            childOpts,
        );

        // Optional dev-only programmatic user. No IAM user is created in prod.
        if (args.createDevIamUser) {
            this.devIamUser = new aws.iam.User(
                `${name}-developer`,
                {
                    forceDestroy: true,
                    tags,
                },
                childOpts,
            );

            new aws.iam.UserPolicyAttachment(
                `${name}-developer`,
                {
                    user: this.devIamUser.name,
                    policyArn: servicePolicy.arn,
                },
                childOpts,
            );

            this.devAccessKey = new aws.iam.AccessKey(
                `${name}-developer`,
                {
                    user: this.devIamUser.name,
                },
                childOpts,
            );
        }

        // ---------------------------------------------------------------------
        // RDS PostgreSQL
        // ---------------------------------------------------------------------

        const subnetGroup = new aws.rds.SubnetGroup(
            `${name}-database`,
            {
                subnetIds: args.privateSubnetIds,
                tags,
            },
            childOpts,
        );

        this.databaseSecurityGroup = new aws.ec2.SecurityGroup(
            `${name}-database`,
            {
                vpcId: args.vpcId,
                description: "PostgreSQL access from application security groups",
                ingress: pulumi
                    .output(args.databaseClientSecurityGroupIds)
                    .apply(securityGroupIds =>
                        securityGroupIds.map(securityGroupId => ({
                            protocol: "tcp",
                            fromPort: 5432,
                            toPort: 5432,
                            securityGroups: [securityGroupId],
                            description: "PostgreSQL from application",
                        })),
                    ),
                egress: [
                    {
                        protocol: "-1",
                        fromPort: 0,
                        toPort: 0,
                        cidrBlocks: ["0.0.0.0/0"],
                    },
                ],
                tags,
            },
            childOpts,
        );

        this.database = new aws.rds.Instance(
            `${name}-postgres`,
            {
                engine: "postgres",
                engineVersion: "16",
                instanceClass: args.databaseInstanceClass,

                allocatedStorage: 20,
                maxAllocatedStorage: 100,
                storageType: "gp3",
                storageEncrypted: true,

                dbName: databaseName,
                username: databaseUsername,
                password: args.databasePassword,
                port: 5432,

                dbSubnetGroupName: subnetGroup.name,
                vpcSecurityGroupIds: [this.databaseSecurityGroup.id],

                publiclyAccessible: false,
                multiAz: args.databaseMultiAz,

                deletionProtection: true,
                backupRetentionPeriod: 7,
                backupWindow: "03:00-04:00",
                maintenanceWindow: "sun:04:00-sun:05:00",

                autoMinorVersionUpgrade: true,
                copyTagsToSnapshot: true,

                // An explicit final snapshot is required when destroying.
                skipFinalSnapshot: false,
                finalSnapshotIdentifier: pulumi
                    .all([pulumi.getStack(), name])
                    .apply(([stack, componentName]) =>
                        `${componentName}-${stack}-final`
                            .toLowerCase()
                            .replace(/[^a-z0-9-]/g, "-"),
                    ),

                tags,
            },
            {
                parent: this,
                protect: true,
            },
        );

        this.databaseConnectionString = pulumi.secret(
            pulumi
                .all([
                    databaseUsername,
                    args.databasePassword,
                    this.database.address,
                    this.database.port,
                    databaseName,
                ])
                .apply(([username, password, host, port, db]) => {
                    const encodedUsername = encodeURIComponent(username);
                    const encodedPassword = encodeURIComponent(password);

                    return (
                        `postgresql://${encodedUsername}:${encodedPassword}` +
                        `@${host}:${port}/${db}?sslmode=require`
                    );
                }),
        );

        this.registerOutputs({
            bucketName: this.bucket.bucket,
            bucketArn: this.bucket.arn,
            replicaBucketName: this.replicaBucket?.bucket,
            databaseAddress: this.database.address,
            databasePort: this.database.port,
            databaseConnectionString: this.databaseConnectionString,
            serviceAccountRoleArn: this.serviceAccountRole.arn,
            devIamUserName: this.devIamUser?.name,
        });
    }
}
```

## Stack entry point: `src/index.ts`

This assumes the VPC, private subnets, EKS OIDC provider, and application security group already exist. Their values can come from another Pulumi stack through `StackReference`.

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { ApplicationData } from "./applicationData";

const config = new pulumi.Config();

const environment = config.require("environment") as "dev" | "prod";
if (environment !== "dev" && environment !== "prod") {
    throw new Error("environment must be either 'dev' or 'prod'");
}

const region = config.require("region") as aws.Region;
const networkStackName = config.require("networkStack");

const dbPassword = config.requireSecret("dbPassword");

const network = new pulumi.StackReference(networkStackName);

const primaryProvider = new aws.Provider("primary", {
    region,
    defaultTags: {
        tags: {
            Environment: environment,
            ManagedBy: "Pulumi",
        },
    },
});

const replicationProvider =
    environment === "prod"
        ? new aws.Provider("replication", {
              region: "us-west-2",
              defaultTags: {
                  tags: {
                      Environment: environment,
                      ManagedBy: "Pulumi",
                  },
              },
          })
        : undefined;

const application = new ApplicationData(
    "web",
    {
        environment,

        vpcId: network.requireOutput("vpcId"),
        privateSubnetIds: network.requireOutput("privateSubnetIds"),

        databaseClientSecurityGroupIds: [
            network.requireOutput("applicationSecurityGroupId"),
        ],

        oidcProviderArn: network.requireOutput("oidcProviderArn"),
        oidcProviderUrl: network.requireOutput("oidcProviderUrl"),

        kubernetesNamespace: "application",
        kubernetesServiceAccount: "web",

        databaseName: "app",
        databaseUsername: "app_admin",
        databasePassword: dbPassword,

        databaseInstanceClass:
            environment === "prod" ? "db.t3.medium" : "db.t3.micro",
        databaseMultiAz: environment === "prod",

        enableReplication: environment === "prod",
        replicationProvider,

        createDevIamUser: environment === "dev",

        tags: {
            Application: "web",
        },
    },
    {
        provider: primaryProvider,
    },
);

export const assetBucketName = application.bucket.bucket;
export const serviceAccountRoleArn = application.serviceAccountRoleArn;
export const databaseAddress = application.database.address;

// Remains encrypted in Pulumi state and is marked secret in CLI/API output.
export const databaseConnectionString =
    application.databaseConnectionString;

// Access-key ID is not secret by itself, but the secret access key is.
export const devAccessKeyId = application.devAccessKey?.id;
export const devSecretAccessKey = application.devAccessKey
    ? pulumi.secret(application.devAccessKey.secret)
    : undefined;
```

## `Pulumi.dev.yaml`

Do not manually place a plaintext password in this file. Set it with `pulumi config set --secret`.

```yaml
config:
  application-infrastructure:environment: dev
  application-infrastructure:region: us-east-1
  application-infrastructure:networkStack: organization/network/dev

  # Created by:
  # pulumi config set --secret dbPassword '...'
  application-infrastructure:dbPassword:
    secure: REPLACE_WITH_PULUMI_GENERATED_CIPHERTEXT
```

## `Pulumi.prod.yaml`

```yaml
config:
  application-infrastructure:environment: prod
  application-infrastructure:region: us-east-1
  application-infrastructure:networkStack: organization/network/prod

  # Created by:
  # pulumi config set --secret dbPassword '...'
  application-infrastructure:dbPassword:
    secure: REPLACE_WITH_PULUMI_GENERATED_CIPHERTEXT
```

Create the stacks and secrets with:

```bash
pulumi stack init dev
pulumi config set environment dev
pulumi config set region us-east-1
pulumi config set networkStack organization/network/dev
pulumi config set --secret dbPassword 'use-a-generated-password'

pulumi stack init prod
pulumi config set environment prod
pulumi config set region us-east-1
pulumi config set networkStack organization/network/prod
pulumi config set --secret dbPassword 'use-a-different-generated-password'
```

The Kubernetes service account must use the emitted role ARN:

```yaml
apiVersion: v1
kind: ServiceAccount
metadata:
  name: web
  namespace: application
  annotations:
    eks.amazonaws.com/role-arn: <serviceAccountRoleArn>
```

Because dev and prod are separate Pulumi stacks, they have independent state, resources, secrets, and configuration. Updating the prod stack does not alter dev state. The RDS resource additionally uses both AWS deletion protection and Pulumi `protect`; intentional deletion requires disabling deletion protection and removing protection first.
